<template>
  <div class="studio" v-if="project">
    <aside><h2>{{ $t("ROM Editor") }}</h2><button v-for="(label,key) in sections" :key="key" :class="{selected:section===key}" @click="navigate(key)">{{$t(label)}}</button><p>{{patches.length}} {{ $t("recursos modificados") }}</p><small>{{$t(saveStatus)}}</small><button v-if="saveError" @click="retrySave">{{ $t("Reintentar guardado") }}</button></aside>
    <div class="workspace">
      <header><button @click="history(false)" :disabled="!canUndo">{{ $t("↶ Deshacer") }}</button><button @click="history(true)" :disabled="!canRedo">{{ $t("↷ Rehacer") }}</button><button class="primary" @click="exportRom">{{ $t("Exportar ROM") }}</button><button @click="createEmptyRom" :disabled="!activeTeams.length">{{ $t("Crear ROM sin equipos") }}</button><button class="delete" @click="resetAllRom">{{ $t("Resetear Todo") }}</button></header>
      <p v-if="error" role="alert" class="error">{{$t(error)}}</p><p v-if="saveError" role="alert" class="error">{{$t(saveError)}} {{ $t("Descarga un proyecto para respaldar tus cambios.") }}</p>
      <section v-if="section==='dashboard'"><h2>{{ $t("International Superstar Soccer Deluxe") }}</h2><p>{{activeTeams.length}} {{$t("equipos")}} · {{activeTeams.length*20}} {{$t("jugadores")}} · {{audioSamples.length}} {{ $t("muestras BRR. Las modificaciones se guardan por hash de la ROM original.") }}</p><p>{{ $t("Puedes agregar equipos hasta completar 48. Cada equipo nuevo comienza con una copia independiente de Italia y aparece en el grupo EXTRA.") }}</p><p>{{ $t("Los nombres de equipo usados por el juego se editan como rótulos gráficos. Las etiquetas del selector identifican los slots originales.") }}</p><p>{{ $t("Para empezar selecciona Jugadores, Apariencia, Gráficos o Audio. La ROM exportada conserva tamaño, mapeo y cabecera; los cambios recalculan checksum y complemento.") }}</p><details><summary>{{ $t("Estructuras aún pendientes") }}</summary><p>{{ $t("Foto de equipo y composición de pantalla principal. Las cinco fotos de portada ya se pueden editar en Gráficos. El logo ya se compone con sus mapas, sprites y paletas originales.") }}</p><p>{{ $t("Pitch por evento, secuencias musicales y bucles del SPC700 pendientes. La previsualización de muestras usa el pitch de inspección elegido, sin afirmar reproducción idéntica al juego.") }}</p></details></section>
      <p v-if="!activeTeams.length" class="notice">{{$t('La ROM no tiene equipos. Agrega el primero desde Equipos para comenzar.')}} <button @click="navigate('teams')">{{$t('Equipos')}}</button></p>
      <template v-if="activeTeams.length && ['teams','players','appearance','graphics'].includes(section)">
        <label>{{ $t("Equipo") }} <select :value="teamIndex" @change="changeTeam($event)"><option v-for="option in teamOptions" :key="option.index" :value="option.index">{{option.number}}. {{$t(option.name)}}</option></select></label>
      </template>
      <section v-if="section==='teams'"><form class="toolbar" @submit.prevent="addTeam"><label>{{$t("Nuevo equipo")}} <input v-model="newTeamName" maxlength="10" :placeholder="$t('Nombre del nuevo equipo')" :disabled="activeTeams.length>=maxTeams" /></label><button class="primary" type="submit" :disabled="!newTeamName.trim()||activeTeams.length>=maxTeams">{{$t("Agregar equipo")}}</button><span>{{activeTeams.length}} / {{maxTeams}}</span></form><p>{{$t("El equipo nuevo copia Italia si está disponible; si fue eliminada, copia el primer equipo existente. Se elige un espacio libre compatible con el nombre. Los espacios originales reutilizados conservan los recursos gráficos compartidos.")}}</p><template v-if="team"><h2>{{ $t("Información general ·") }} {{$t(teams[teamIndex])}}</h2><div class="toolbar"><button @click="removeTeam" :disabled="!teamSelectable||playerTeams.length<=1">{{$t("Eliminar equipo de los grupos")}}</button><button @click="deleteTeam" :disabled="activeTeams.length<=1">{{$t("Eliminar físicamente de la ROM")}}</button><span>{{playerTeams.length}} {{$t("equipos en los grupos seleccionables")}}</span></div><p>{{$t("Eliminar quita el equipo de todos los grupos. Sus datos y referencias en Scenarios se conservan; no libera un espacio adicional. Puedes deshacer o volver a incluirlo desde Grupos.")}}</p><p>{{$t("La eliminación física borra los datos exclusivos del equipo y libera su espacio para crear otro. Los datos compartidos se conservan y las referencias del juego se redirigen a un equipo existente. Puedes deshacer el cambio.")}}</p><p v-if="!teamSelectable" class="notice">{{$t("Este equipo está fuera de los grupos seleccionables.")}}</p><p>{{$t("Los nombres de jugadores admiten 8 caracteres. Los nombres grandes de equipos dependen del espacio gráfico de cada slot; los pequeños deben caber en 32 píxeles. Ampliar estos límites requiere modificar las rutinas de la ROM.")}}</p><p>{{ $t("Nombre en juego: rótulo gráfico 2bpp de") }} {{team.teamMatrix[0].length}} × {{team.teamMatrix.length}}{{ $t(". La etiqueta del selector identifica el slot original.") }}</p><RomImage :matrix="team.teamMatrix" :colors="team.teamColors" :label="$t(&quot;Nombre gráfico del equipo&quot;)" /><button @click="editTeamLabel">{{ $t("Editar rótulo") }}</button><FormationEditor ref="formationEditor" :rom="rom" :original="project.original" :team-index="teamIndex" :players="team.players" :team-options="activeTeams.map(index=>({index,name:teams[index]}))" :modified="isModified(formation.id)" @apply="applyFormationChanges" @restore="restoreResource(formation.id)" /></template></section>
      <MenusEditor v-if="section==='mainMenu'" ref="mainMenu" :rom="rom" :original="project.original" :error="error" @change="updateMainMenu" />
      <StadiumEditor ref="stadiumsEditor" v-if="section==='stadiums'" :rom="rom" :original="project.original" :modified="patches.map(p=>p.id)" :apply-error="error" @apply="updateStadium" @restore="restoreStadium" @restore-all="restoreStadiums" />
      <ScenarioEditor ref="scenariosEditor" v-if="activeTeams.length && section==='scenarios'" :scenarios="scenarios" :rom="rom" :stadium-names="stadiums.map(s=>s.name)" :teams="groupTeamNames" :modified="patches.filter(p=>p.id.startsWith('scenario:')||p.id.startsWith('scenario-text:')||p.id.startsWith('scenario-difficulty:')).map(p=>p.id)" @change="updateScenario" @difficulty-change="updateScenarioDifficulty" @description-change="updateScenarioDescription" @restore="restoreScenario" @restore-all="restoreScenarios" />
      <GroupEditor v-if="activeTeams.length && section==='groups'" :groups="groups" :columns="flagColumns" :teams="groupTeamNames" :modified="customGroups" @change="updateGroups" @restore="restoreGroups" />
      <section v-if="activeTeams.length && section==='players'">
        <h2>{{ $t("Jugadores ·") }} {{$t(teams[teamIndex])}}</h2><p v-if="team.sharedPlayerNames" class="notice">{{ $t("Los nombres de estos jugadores se comparten con sus selecciones de origen. Editar un nombre también lo cambia allí; los atributos pertenecen al equipo de estrellas.") }}</p><p>{{ $t("Dorsales/identificadores únicos (1–20): elegir uno ya asignado intercambia ambos valores.") }}</p>
        <div class="toolbar"><input v-model="search" :placeholder="$t(&quot;Buscar jugador&quot;)" :aria-label="$t(&quot;Buscar jugador&quot;)" /><select v-model="positionFilter" :aria-label="$t(&quot;Filtrar posición&quot;)"><option value="">{{ $t("Todas las posiciones") }}</option><option v-for="(name,id) in positions" :key="id" :value="id">{{$t(name)}}</option></select><label>{{ $t("Orden") }} <select v-model="sortKey"><option value="index">{{ $t("Slot") }}</option><option value="no">{{ $t("Dorsal") }}</option><option value="name">{{ $t("Nombre") }}</option><option value="position">{{ $t("Posición") }}</option></select></label></div>
        <div class="toolbar"><span>{{selectedPlayers.length}} {{ $t("seleccionados") }}</span><select v-model="batchStat" :aria-label="$t(&quot;Atributo para cambio múltiple&quot;)"><option v-for="s in stats" :key="s" :value="s">{{$t(s)}}</option></select><input type="number" min="1" max="10" v-model.number="batchValue" :aria-label="$t(&quot;Valor para cambio múltiple&quot;)" /><button @click="batch" :disabled="!selectedPlayers.length">{{ $t("Aplicar a seleccionados") }}</button><label>{{ $t("Copiar plantilla") }} <select v-model.number="copySource"><option v-for="option in playerTeams" :key="option.index" :value="option.index">{{$t(option.name)}}</option></select></label><button @click="copyRoster">{{ $t("Copiar sus 20 jugadores") }}</button></div>
        <div class="table-scroll"><table class="players-table"><thead><tr><th><input type="checkbox" :aria-label="$t(&quot;Seleccionar jugadores visibles&quot;)" @change="selectAll($event.target.checked)" /></th><th>{{ $t("Dorsal") }}</th><th>{{ $t("Nombre") }}</th><th>{{ $t("Posición") }}</th><th class="hair-column">{{ $t("Pelo") }}</th><th class="skin-column">{{ $t("Piel") }}</th><th>{{ $t("Atributos") }}</th><th>{{ $t("Restaurar") }}</th></tr></thead>
          <tbody><tr v-for="row in rows" :key="row.index" :class="{modified:isPlayerModified(row.index)}"><td><input type="checkbox" :value="row.index" v-model="selectedPlayers" :aria-label="$t(`Seleccionar ${row.player.name}`)" /></td><td><input class="number" type="number" min="1" max="20" :value="row.player.no" @change="editPlayer(row.index,'no',Number($event.target.value),$event)" /></td><td><input class="name" maxlength="8" :value="row.player.name" @change="editPlayer(row.index,'name',$event.target.value,$event)" /></td><td><select :value="row.player.position" @change="editPlayer(row.index,'position',Number($event.target.value),$event)"><option v-for="(name,id) in positions" :key="id" :value="id">{{$t(name)}}</option></select></td>
            <td class="hair-column"><button class="hair" @click="hairPlayer=row.index"><RomImage compact :matrix="row.player.head" :colors="row.player.headColors" :label="$t(`Pelo ${row.player.hair}`)" /><span>{{row.player.hair}}</span></button></td>
            <td class="skin-column"><div class="skin-cell"><input type="color" class="skin-color" :value="row.player.skinColor" @change="skinColor(row.index,$event.target.value,$event)" :title="$t('Edita un color de paleta; puede afectar varios jugadores')" /><select :value="row.player.skin" @change="editPlayer(row.index,'skin',Number($event.target.value),$event)"><option :value="0">{{ $t("Normal") }}</option><option :value="1">{{ $t("Alternativa") }}</option></select></div></td>
            <td><details><summary>{{ $t("Estadísticas") }}</summary><label v-for="stat in stats" :key="stat" class="player-stat"><span>{{$t(stat)}}</span><input type="range" min="1" max="10" step="1" :value="row.player[stat]" @input="editPlayer(row.index,stat,Number($event.target.value),$event)" /><output>{{row.player[stat]}}</output></label></details></td><td><button @click="restorePlayer(row.index)" :disabled="!isPlayerModified(row.index)">↺</button></td></tr></tbody></table></div>
      </section>
      <section v-if="activeTeams.length && section==='appearance'"><h2>{{ $t("Uniformes y portero") }}</h2><label>{{ $t("Paleta") }} <select v-model.number="paletteTable"><option :value="0x1027a">{{ $t("Tipo 1 / local") }}</option><option :value="0x102d0">{{ $t("Tipo 2 / visitante") }}</option><option :value="0x10326">{{ $t("Portero") }}</option><option :value="0xe7d8">{{ $t("Bandera") }}</option><option :value="0x1037c">{{ $t("Piel alternativa") }}</option><option :value="0x103d2">{{ $t("Pelo alternativo") }}</option></select></label><p>{{ $t("El cambio se convierte a BGR555. Los colores de piel/pelo alternativo y algunos gráficos se comparten entre equipos.") }}</p>
        <div v-if="paletteData" class="palette-editor"><label v-for="(color,i) in paletteData.colors" :key="i">{{i}} <input type="color" :value="color" @change="editPalette(paletteData.offset+i*2,$event.target.value,$event)" /><button @click="restoreResource(`palette:${paletteData.offset+i*2}`)" :disabled="!isModified(`palette:${paletteData.offset+i*2}`)">↺</button></label></div><p v-else>{{ $t("Este equipo no tiene un registro alternativo de este tipo.") }}</p>
        <div class="previews"><figure><RomImage :matrix="originalUniformMatrix" :colors="uniformColors(false)" :label="$t(&quot;Uniforme original&quot;)" /><figcaption>{{ $t("Original") }}</figcaption></figure><figure><RomImage :matrix="uniformMatrix" :colors="uniformColors(true)" :label="$t(&quot;Uniforme modificado&quot;)" /><figcaption>{{ $t("Modificado") }}</figcaption></figure></div><button @click="navigate('graphics')">{{ $t("Editar sprites y detalles") }}</button></section>
      <section v-if="activeTeams.length && section==='graphics'"><h2>{{ $t("Pixel Art Maker") }}</h2><select :value="graphic.id" :aria-label="$t(&quot;Seleccionar gráfico&quot;)" @change="changeGraphic($event)"><option v-for="resource in resources" :key="resource.id" :value="resource.id">{{$t(resource.label)}}</option></select><p>{{$t(graphic.label)}} · {{$t((graphic.kind==='composite'||graphic.kind==='screen-text'&&graphic.bpp===8)?'Capas 4bpp':graphic.bpp+'bpp')}} · {{$t(originalGraphic.capacity)}} {{ $t("bytes disponibles") }}</p><p v-if="graphic.kind==='composite'" class="notice">{{ $t("Este recurso modifica el logo global de la portada.") }}</p><p v-else-if="graphic.kind==='boot-screen'" class="notice">{{ $t("Pantalla inicial de 256 × 224. Puedes dibujar o importar una imagen. Se conservan los efectos de la introducción y las paletas originales; cada bloque de 8 × 8 usa una paleta. Las imágenes con demasiado detalle pueden superar el espacio disponible.") }}</p><p v-else-if="graphic.kind==='portrait'" class="notice">{{ $t("Foto global de la pantalla principal. Puedes dibujar o importar una imagen usando sus colores originales. Las cinco fotos comparten espacio comprimido; el dibujo debe caber en los bytes disponibles.") }}</p><p v-else-if="graphic.kind==='title-legal'" class="notice">{{ $t("Texto gráfico de la pantalla inicial. Puedes dibujar o importar una imagen; cada leyenda se modifica de forma independiente. Se conserva PRESS START.") }}</p><p v-else-if="graphic.kind==='group-label'" class="notice">{{ $t("Rótulo de la selección de equipos. Cada grupo tiene gráficos independientes: cambiar un título no modifica los demás. Los cambios se guardan en un espacio reservado separado de la fuente original.") }}</p><p v-else-if="graphic.kind==='screen-text'" class="notice">{{ $t("Texto armado con sus tiles y paletas originales. Puedes dibujar o importar una imagen. Las letras y sus reflejos reutilizan píxeles; editar la fuente de los títulos también cambia sus otras apariciones. El texto de contraseña comparte letras con otros menús. Los colores se ajustan a la paleta de cada zona.") }}</p><p v-else-if="graphic.kind==='menu-layer'" class="notice">{{ $t("La imagen está armada como en el juego. Los píxeles reutilizados cambian en todas sus apariciones; el borde sombreado sirve de referencia.") }}</p><p v-else-if="graphic.shared" class="notice">{{ $t("Recurso compartido: editar sus tiles afecta a todos los equipos que usan este sprite.") }}</p><p v-else-if="graphic.kind==='label'" class="notice">{{ $t("El rótulo se guarda por equipo en un espacio reservado de 69 bytes; cualquier dibujo de 32 × 8 cabe.") }}</p><p v-else class="notice">{{ $t("Las banderas se guardan por equipo y no cambian las de otros países. Los rótulos conservan sus referencias originales.") }}</p><p v-if="graphic.kind==='composite'&&graphic.label.includes('Logo')">{{ $t("Logo armado con sus dos capas y texto original. Los colores se ajustan a la paleta de la capa editada. El fondo sin tiles propios no se puede dibujar.") }}</p>
        <div v-if="graphic.kind==='title-legal'">
          <label>{{ $t("Texto de portada") }} <input type="text" v-model="titleLegalText" :maxlength="graphic.maxLength" @input="previewTitleText" /></label>
          <p>{{ $t("Hasta") }} {{graphic.maxLength}} {{ $t("caracteres: A–Z, números, espacios, puntos, guiones o ©.") }}</p>
          <p v-if="titleTextError" class="error" role="alert">{{$t(titleTextError)}}</p>
          <RomImage v-if="titleTextPreview" :matrix="titleTextPreview.matrix" :colors="graphic.colors" :label="$t('Previsualización del texto de portada')" />
          <button v-if="titleTextPreview" @click="applyTitleText">{{ $t("Aplicar texto de portada a la ROM") }}</button>
          <button v-if="titleTextPreview||titleTextError" @click="discardTitleText">{{ $t("Descartar previsualización") }}</button>
        </div>
        <div v-if="graphic.kind==='group-label'"><label>{{ $t("Texto del grupo") }} <input v-model="groupNameText" maxlength="15" @input="previewGroupName" /></label><p v-if="groupTextError" class="error" role="alert">{{$t(groupTextError)}}</p><RomImage v-if="groupPreview" :matrix="groupPreview.matrix" :colors="graphic.colors" :label="$t('Previsualización del grupo')" /><button v-if="groupPreview" @click="applyGroupName">{{ $t("Aplicar texto del grupo a la ROM") }}</button><button v-if="groupPreview||groupTextError" @click="discardGroupText">{{ $t("Descartar previsualización") }}</button></div>
        <div v-if="graphic.label==='Rótulo del equipo'">
          <h3>{{ $t("Nombres independientes del equipo") }}</h3>
          <div class="name-editors">
            <div><label>{{ $t("Nombre rojo y amarillo") }} <input v-model="bigNameText" :maxlength="largeLabel.maxLetters" @input="previewTeamName" /></label><p>{{ $t("Hasta") }} {{$t(largeLabel.maxLetters)}} {{ $t("caracteres A–Z, puntos y espacios.") }}</p><RomImage :matrix="namePreview?.large.matrix||largeLabel.matrix" :colors="largeLabel.colors" :label="$t(&quot;Previsualización del nombre rojo y amarillo&quot;)" /><p v-if="namePreview?.errors.large" role="alert" class="error">{{$t(namePreview.errors.large)}}</p></div>
            <div><label>{{ $t("Nombre pequeño") }} <input v-model="smallNameText" maxlength="32" @input="previewTeamName" /></label><p>{{graphic.matrix[0].length}} × {{graphic.matrix.length}} {{ $t("px · A–Z, puntos y espacios.") }}</p><RomImage :matrix="namePreview?.small.matrix||graphic.matrix" :colors="graphic.colors" :label="$t(&quot;Previsualización del nombre pequeño&quot;)" /><p v-if="namePreview?.errors.small" role="alert" class="error">{{$t(namePreview.errors.small)}}</p></div>
          </div>
          <div v-if="namePreview"><button @click="applyTeamName" :disabled="!!namePreview.errors.small||!!namePreview.errors.large">{{ $t("Aplicar nombres a la ROM") }}</button><button @click="discardTeamName">{{ $t("Descartar previsualización") }}</button></div>
          <button @click="restoreTeamName">{{ $t("Restaurar ambos nombres de este equipo") }}</button><p>{{ $t("La previsualización cambia al escribir. Cada campo modifica su propia imagen; el dibujo libre de abajo modifica el rótulo pequeño.") }}</p>
        </div>
        <p v-if="graphic.kind==='sprite'&&graphic.editableParts?.length===1">{{ $t("Edita la zona clara del pecho sobre el uniforme. Las demás partes del jugador sirven de contexto. Este patrón puede repetirse en otros equipos.") }}</p><PixelEditor :normalize-image="graphic.kind==='boot-screen'?normalizeBootImage:null" :flag="graphic.kind==='flag'" :apply-error="error" ref="pixel" :key="graphic.id" :matrix="graphic.matrix" :editable="graphic.editable" :import-editable="originalGraphic.importEditable" :highlight-editable="graphic.kind==='sprite'&&graphic.editableParts?.length===1" :original="originalGraphic.matrix" :original-colors="originalGraphic.colors" :colors="graphic.colors" @apply="applyGraphic" /><button @click="restoreGraphic" :disabled="!graphicModified">{{ $t("Restaurar recurso en ROM") }}</button>
      </section>
      <section v-if="section==='audio'"><h2>{{ $t("Audio · muestras BRR") }}</h2><p>{{ $t("Las muestras no contienen una frecuencia WAV. El DSP consume 32000 × pitch / 4096 muestras/s. El juego calcula el pitch por evento; esos eventos aún no están vinculados al catálogo. Este control es de inspección.") }}</p><select v-model.number="sampleIndex" @change="changeAudioSample"><option v-for="(sample,i) in audioSamples" :key="i" :value="i">{{$t(sample.name)}}</option></select><label>{{ $t("Pitch DSP") }} <input type="number" min="1" max="16383" v-model.number="pitch" @change="changeAudioPitch" /></label><span>{{audioRate.toFixed(2)}} {{ $t("Hz") }}</span><button @click="previewAudio">{{ $t("Previsualizar ROM") }}</button><label><input type="checkbox" v-model="audioLoop" /> {{ $t("Repetir preview") }}</label><p>{{$t(audioInfo.capacity)}} {{ $t("bytes BRR disponibles ·") }} {{(audioInfo.capacity/9*16/audioRate).toFixed(3)}} {{ $t("s de capacidad") }}</p><p v-if="audioInfo.reason" class="notice">{{$t(audioInfo.reason)}} {{ $t("Reemplazo WAV deshabilitado.") }}</p><p v-if="audioInfo.segmented" class="notice">{{ $t("Este audio de portada contiene cuatro fragmentos que el juego activa por separado, incluido un bucle inicial. Se conservan sus límites y marcas de reproducción al aplicar el recorte; la previsualización los reproduce seguidos.") }}</p><p>{{ $t("La música secuenciada requiere editar eventos/instrumentos y emular el SPC700. Las muestras musicales listadas son fragmentos o instrumentos, no un editor de canciones.") }}</p><p>{{ $t("Los recortes se normalizan automáticamente al mismo nivel de señal, con protección de picos. El volumen final también depende del evento y la envolvente del juego.") }}</p><button @click="normalizeAppliedAudio" :disabled="!modifiedAudioCount||audioBusy">{{ $t("Normalizar audios modificados (") }}{{$t(modifiedAudioCount)}})</button><p v-if="audioNormalizeStatus" role="status">{{$t(audioNormalizeStatus)}}</p><AudioTrim :source="audioSource" :max-duration="audioCapacitySeconds" :disabled="!!audioInfo.reason" :busy="audioBusy" @upload="importAudioFile" @range="prepareAudioTrim" @preview="playAudioTrim" @discard="discardAudioImport" /><p v-if="audioReplacement">{{ $t("Recorte normalizado y convertido a BRR:") }} {{audioReplacement.patch.bytes.length}} {{ $t("bytes. El espacio restante se rellena con silencio. Escucha el resultado antes de aplicarlo.") }}</p><p v-if="audioUrl" role="status">{{$t(audioPreviewLabel)}}</p><audio v-if="audioUrl" ref="audio" :src="audioUrl" controls :loop="audioLoop" /><button v-if="audioUrl" @click="$refs.audio.pause();$refs.audio.currentTime=0">{{ $t("Detener") }}</button><canvas v-show="audioUrl" ref="waveform" width="700" height="100" class="waveform" :aria-label="$t(&quot;Forma de onda&quot;)" /><button @click="applyAudio" :disabled="!audioReplacement">{{ $t("Aplicar recorte a la ROM") }}</button><button @click="restoreAudio" :disabled="!isModified(`audio:${audioInfo.offset}`)">{{ $t("Restaurar muestra") }}</button></section>
      <RomEmulator :key="$locale" v-if="activeTeams.length && section==='emulator'" ref="emulator" :project="project" :revision="revision" />
      <section v-if="section==='settings'"><h2>{{ $t("Configuración") }}</h2><label>{{ $t("Columnas de banderas") }} <select :value="flagColumns" @change="setFlagColumns(Number($event.target.value))"><option :value="3">{{ $t("3 columnas · 2 filas") }}</option><option :value="4">{{ $t("4 columnas · 1 fila") }}</option></select></label><p>{{ $t("La ROM exportada usa esta distribución. Los grupos se dividen en páginas de seis o cuatro equipos según la opción elegida.") }}</p><label>{{ $t("ALL STARS en la selección de equipos") }} <select :disabled="customGroups" :value="allStarsVisibility" @change="setAllStars($event.target.value)"><option v-if="customGroups" value="groups">{{ $t("Controlado por el editor de Grupos") }}</option><option value="original">{{ $t("Comportamiento de la ROM original") }}</option><option value="visible">{{ $t("Siempre visible") }}</option><option value="hidden">{{ $t("Siempre oculto") }}</option></select></label><p v-if="customGroups" class="notice">{{ $t("La selección usa los grupos configurados. Restaura los grupos originales para cambiar la visibilidad de ALL STARS.") }}</p><p>{{ $t("Esta opción modifica la ROM exportada. Siempre oculto también desactiva la página después del código de desbloqueo. Los seis equipos All-Star siguen disponibles para editar.") }}</p></section>
      <section v-if="section==='project'"><h2>{{ $t("Proyecto y cambios") }}</h2><p>{{ $t("SHA-256:") }} <code>{{project.hash}}</code></p><p>{{$t(saveStatus)}}</p><button @click="exportProject">{{ $t("Descargar proyecto editable") }}</button><label>{{ $t("Importar proyecto") }} <input type="file" accept=".json" @change="importProject" /></label><button @click="reset">{{ $t("Restaurar todo") }}</button><p>{{ $t("El proyecto descargado incluye tu ROM original y modificaciones. El archivo se conserva localmente.") }}</p><ul><li v-for="patch in patches" :key="patch.id">{{$t(patch.label)}} {{ $t("· 0x") }}{{patch.offset.toString(16)}} · {{patch.bytes.length}} {{ $t("bytes") }} <button @click="restoreResource(patch.id)">{{ $t("Restaurar") }}</button></li></ul><p v-if="!patches.length">{{ $t("Sin modificaciones. La exportación será idéntica al archivo original.") }}</p><p>{{ $t("La exportación valida todos los recursos y equipos. Usa el menú Emulador para probar la ROM con los cambios aplicados.") }}</p></section>
      <dialog ref="hairDialog" v-if="hairPlayer!==null" class="hair-dialog" @cancel="hairPlayer=null"><h3>{{ $t("Elegir pelo ·") }} {{team.players[hairPlayer].name}}</h3><div class="hair-options"><button v-for="(option,i) in hairOptions" :key="i" @click="editPlayer(hairPlayer,'hair',i);hairPlayer=null"><RomImage compact :matrix="option.head" :colors="option.headColors" :label="$t(`Estilo ${i}`)" />{{i}}</button></div><button @click="hairPlayer=null">{{ $t("Cerrar") }}</button></dialog>
    </div>
  </div><p v-else role="status">{{$t(error||'Preparando proyecto…')}}</p>
</template>
<script>
import {markRaw} from 'vue';
import {mainMenuGraphics} from '../rom/main-menu.mjs';
import MenusEditor from './MenusEditor.vue';
import GroupEditor from './GroupEditor.vue';
import ScenarioEditor from './ScenarioEditor.vue';
import StadiumEditor from './StadiumEditor.vue';
import {readStadiums,STADIUM_RULES,stadiumGraphicRules,restoreStadiumPatches} from '../rom/stadiums.mjs';
import {scenarioStartChanges} from '../rom/scenario-position.mjs';
import {readScenarioSummary} from '../rom/scenario-summary.mjs';
import {readScenarioDescription,scenarioDescriptionPatch,SCENARIO_TEXT_RULES} from '../rom/scenario-text.mjs';
import {readScenarios,scenarioPatch,SCENARIO_RULES,SCENARIO_DIFFICULTY_RULES,scenarioDifficultyPatch} from '../rom/scenarios.mjs';
import {editableGroups,editGroupsPatches} from '../rom/group-editor.mjs';
import {hasCustomGroups,groupColumns} from '../rom/groups.mjs';
import {groupTexts,previewGroupText,groupTextPatches,restoreGroupTextPatches} from '../rom/group-text.mjs';
import {allStarsMode,allStarsPatch} from '../rom/selection.mjs';
import RomEmulator from './RomEmulator.vue';
import {bootScreenPreview} from '../rom/boot-screens.mjs';
import RomImage from './RomImage.vue';import PixelEditor from './PixelEditor.vue';import AudioTrim from './AudioTrim.vue';
import FormationEditor from './FormationEditor.vue';
import {readFormation} from '../rom/formations.mjs';
import {RomProject} from '../rom/project.mjs';import {loadProject,storeProject} from '../rom/project-store.mjs';
import {MAX_TEAMS,teamCount,teamPointer,teamExists,activeTeamIds,hasPhysicalTeams,teamDataRom} from '../rom/team-count.mjs';
import {DELUXE_TEAMS,readDeluxeTeam} from '../rom/deluxe.mjs';import {playerOffsets,playerPatches,POSITIONS,STATS} from '../rom/players.mjs';import {deluxeAppearance} from '../rom/appearance.mjs';
import {bigLabel,bigTeamNamePatches,smallTeamNamePatches,teamNameTexts,previewBigTeamText,compactTeamName,restoreTeamLabelPatches} from '../rom/team-labels.mjs';
import {previewTitleLegalText,titleLegalTextPatches} from '../rom/title-legal.mjs';
import {word,loRom,palette,tiles} from '../rom/binary.mjs';import {graphicResources,graphicPatches,flagPatches,smallLabelPatches,flagPalettePatches,rgb555} from '../rom/graphics.mjs';
import {AUDIO_SAMPLES,readAudioSample,wavBlob} from '../rom/audio.mjs';import {audioRegion,pitchRate,decodeUploadedAudio,trimAudio,replacementAudio,normalizedAudioPatches} from '../rom/audio-edit.mjs';
const download=(bytes,name,type)=>{const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
export default {
  components:{FormationEditor,StadiumEditor,ScenarioEditor,MenusEditor,GroupEditor,RomImage,PixelEditor,AudioTrim,RomEmulator},props:{input:Uint8Array},emits:['import-rom'],
  data(){return {project:null,rom:null,revision:0,teamIndex:0,team:null,error:'',saveError:'',saveStatus:'',storageBlocked:false,saveChain:Promise.resolve(),loadVersion:0,saveVersion:0,section:'dashboard',sections:{dashboard:'Resumen',teams:'Equipos',groups:'Grupos',players:'Jugadores',appearance:'Apariencia',graphics:'Gráficos',mainMenu:'Menus',scenarios:'Scenarios',stadiums:'Estadios',audio:'Audio',emulator:'Emulador',settings:'Configuración',project:'Proyecto'},newTeamName:'',maxTeams:MAX_TEAMS,positions:POSITIONS,stats:STATS,search:'',sortKey:'index',positionFilter:'',selectedPlayers:[],batchStat:'speed',batchValue:5,copySource:0,hairPlayer:null,paletteTable:0x1027a,graphicId:'',titleLegalText:'',titleTextPreview:null,titleTextError:'',groupNameText:'',groupPreview:null,groupTextError:'',bigNameText:'',smallNameText:'',committedNames:{small:'',large:''},namePreview:null,audioSamples:AUDIO_SAMPLES,sampleIndex:0,pitch:1300,audioUrl:'',audioPreviewLabel:'',audioLoop:false,audioReplacement:null,audioSource:null,audioRange:null,audioBusy:false,audioDecodeVersion:0,audioNormalizeStatus:''};},
  computed:{
    activeTeams(){return activeTeamIds(this.rom);},
    teams(){return Array.from({length:teamCount(this.rom)},(_,i)=>!teamExists(this.rom,i)?null:i<42&&!hasPhysicalTeams(this.rom)?DELUXE_TEAMS[i]:teamNameTexts(this.project.original,this.rom,i).large||teamNameTexts(this.project.original,this.rom,i).small||`TEAM ${i+1}`);},
    patches(){this.revision;return this.project.patches;},canUndo(){this.revision;return this.project.canUndo;},canRedo(){this.revision;return this.project.canRedo;},
    stadiums(){return readStadiums(this.rom);},
    scenarios(){return readScenarios(this.rom).map(s=>({...s,description:readScenarioDescription(this.rom,s.index).text,descriptionId:`scenario-text:${s.index}`,summary:readScenarioSummary(this.rom,s.index).lines}));},
    flagColumns(){return groupColumns(this.rom);},groups(){return editableGroups(this.rom);},customGroups(){return hasCustomGroups(this.rom);},
    groupTeamNames(){return this.teams.map((name,i)=>{if(!teamExists(this.rom,i))return null;const current=teamNameTexts(this.project.original,this.rom,i),baseline=teamNameTexts(this.project.original,this.project.original,i);return current.large!==baseline.large?current.large:current.small!==baseline.small?current.small:name;});},
    playerTeams(){return [...new Set(this.groups.flatMap(group=>group.teams))].map(index=>({index,name:this.teams[index]}));},
    teamSelectable(){return this.groups.some(group=>group.teams.includes(this.teamIndex));},
    teamOptions(){const options=this.section==='players'?this.playerTeams:this.activeTeams.map(index=>({index,name:this.teams[index]}));return options.map(option=>({...option,number:this.activeTeams.indexOf(option.index)+1}));},
    allStarsVisibility(){return allStarsMode(this.rom);},
    formation(){return readFormation(this.rom,this.teamIndex);},
    rows(){return this.team.players.map((player,index)=>({player,index})).filter(r=>r.player.name.toLowerCase().includes(this.search.toLowerCase())&&(!this.positionFilter||r.player.position===Number(this.positionFilter))).sort((a,b)=>{const k=this.sortKey,av=k==='index'?a.index:a.player[k],bv=k==='index'?b.index:b.player[k];return typeof av==='string'?av.localeCompare(bv):av-bv;});},
    hairOptions(){const player=this.team.players[this.hairPlayer]||this.team.players[0];return Array.from({length:14},(_,hair)=>deluxeAppearance(this.rom,this.teamIndex,{...player,hair}));},
    resources(){if(!this.activeTeams.length)return [];const names=groupTexts(this.rom);return graphicResources(this.rom,this.teamIndex).map(r=>r.kind==='group-label'?{...r,label:names[Number(r.id.split(':')[1])]}:r);},graphic(){return this.resources.find(r=>r.id===this.graphicId)||this.resources[0]||{};},originalGraphic(){const created=this.project.originalTeamGraphic(this.teamIndex,this.graphic.kind);if(created)return {...this.graphic,...created};if(this.graphic.id==='main-menu:font')return mainMenuGraphics(this.project.original,true)[0];const original=graphicResources(this.project.original,this.teamIndex).find(r=>r.id===this.graphic.id);if(original)return original;return {...this.graphic,matrix:previewGroupText(this.project.original,this.graphic,`GRUPO ${Number(this.graphic.id.split(':')[1])+1}`).matrix};},
    largeLabel(){return {...bigLabel(this.rom,this.teamIndex),maxLetters:bigLabel(this.project.original,this.teamIndex).maxLetters};},
    graphicModified(){const r=this.graphic,originalBytes=this.project.original;if(['portrait','group-label'].includes(r.kind))return JSON.stringify(r.matrix)!==JSON.stringify(this.originalGraphic.matrix);if(r.parts)return this.originalGraphic.parts.some((p,i)=>(!r.editableParts||r.editableParts.includes(i))&&this.rom.subarray(p.offset,p.offset+p.capacity).some((b,j)=>b!==originalBytes[p.offset+j]));const original=this.originalGraphic;return JSON.stringify(this.graphic.matrix)!==JSON.stringify(original.matrix)||JSON.stringify(this.graphic.colors)!==JSON.stringify(original.colors);},
    paletteData(){const pointer=teamPointer(this.rom,this.paletteTable,this.teamIndex);if(!pointer)return null;const offset=loRom(0x890000|pointer)+2,count=(word(this.rom,offset-2)+1)/2;return {offset,colors:palette(this.rom,offset,count)};},
    uniformMatrix(){return this.resources.find(r=>r.label.startsWith(this.paletteTable===0x10326?'Portero completo':'Jugador completo')).matrix;},
    originalUniformMatrix(){return graphicResources(this.project.original,this.teamIndex).find(r=>r.label.startsWith(this.paletteTable===0x10326?'Portero completo':'Jugador completo')).matrix;},
    modifiedAudioCount(){this.revision;return this.project?this.project.patches.filter(p=>p.id.startsWith('audio:')).length:0;},
    audioRate(){try{return pitchRate(this.pitch);}catch{return 1;}},audioInfo(){return audioRegion(this.rom,this.audioSamples[this.sampleIndex]);},audioCapacitySeconds(){return this.audioInfo.capacity/9*16/this.audioRate;},
  },
  watch:{hairPlayer(value){if(value!==null)this.$nextTick(()=>this.$refs.hairDialog?.showModal());},input(){this.initialize();}},mounted(){this.initialize();window.addEventListener('keydown',this.shortcuts);window.addEventListener('beforeunload',this.beforeLeave);},beforeUnmount(){this.loadVersion++;this.clearAudio();window.removeEventListener('keydown',this.shortcuts);window.removeEventListener('beforeunload',this.beforeLeave);},
  methods:{
    createEmptyRom(){if(!this.allowNavigate())return;if(!confirm(this.$t('¿Crear una ROM sin equipos? Podrás agregar equipos nuevos y deshacer esta operación.')))return;this.act(()=>{this.project.createEmptyRom();this.section='teams';this.graphicId='';this.selectedPlayers=[];this.hairPlayer=null;this.changed();});},
    addTeam(){if(!this.allowNavigate())return;this.act(()=>{const before=new Set(this.activeTeams);this.project.addTeam(this.newTeamName);this.teamIndex=activeTeamIds(this.project.bytes()).find(i=>!before.has(i));this.newTeamName='';this.graphicId='';this.changed();});},
    removeTeam(){if(!this.allowNavigate())return;if(!confirm(this.$t('¿Quitar este equipo de todos los grupos seleccionables? Puedes deshacer este cambio.')))return;this.act(()=>{this.project.removeTeam(this.teamIndex);this.selectedPlayers=[];this.hairPlayer=null;this.changed();});},
    deleteTeam(){if(!this.allowNavigate())return;if(!confirm(this.$t('¿Borrar físicamente este equipo de la ROM y liberar su espacio? Sus referencias se redirigirán a otro equipo. Puedes deshacer el cambio.')))return;this.act(()=>{this.project.deleteTeam(this.teamIndex);this.graphicId='';this.selectedPlayers=[];this.hairPlayer=null;this.changed();});},
    normalizeBootImage(matrix){return bootScreenPreview(this.graphic,matrix).matrix;},
    async initialize(){this.$refs.emulator?.stop();const version=++this.loadVersion;this.error='';this.saveError='';this.storageBlocked=false;this.clearAudio();try{let project=await RomProject.create(this.input);try{const saved=await loadProject(project.hash);if(saved){try{project=await RomProject.import(saved);}catch(e){this.storageBlocked=true;throw e;}}}catch(e){this.saveError=`No se pudo restaurar el guardado: ${e.message}`;}if(version!==this.loadVersion)return;this.project=markRaw(project);this.teamIndex=0;this.graphicId='';this.refresh();if(!this.storageBlocked)this.save();else this.saveStatus='Guardado anterior no validado';}catch(e){this.error=e.message;}},
    refresh(){this.rom=markRaw(this.project.bytes());if(!teamExists(this.rom,this.teamIndex))this.teamIndex=activeTeamIds(this.rom)[0];if(!teamExists(this.rom,this.copySource))this.copySource=this.teamIndex;this.syncPlayerTeams();this.team=this.activeTeams.length?readDeluxeTeam(this.rom,this.teamIndex):null;this.revision++;this.discardTeamName();this.discardGroupText();this.discardTitleText();},
    syncPlayerTeams(){if(this.section!=='players'||!this.activeTeams.length)return;const options=this.playerTeams;if(!options.some(option=>option.index===this.teamIndex)){this.teamIndex=options[0].index;this.selectedPlayers=[];this.hairPlayer=null;}if(!options.some(option=>option.index===this.copySource))this.copySource=options[0].index;},
    changed(){this.refresh();this.save();},
    retrySave(){if(this.storageBlocked&&!confirm(this.$t('El guardado anterior no pudo validarse. ¿Reemplazarlo por el proyecto actual?')))return;this.storageBlocked=false;this.save();},
    save(){if(this.storageBlocked)return;const record=this.project.record(),version=++this.saveVersion;this.saveStatus='Guardando…';this.saveChain=this.saveChain.catch(()=>{}).then(()=>storeProject(record)).then(()=>{if(version===this.saveVersion){this.saveStatus=`Guardado: ${new Date().toLocaleString(this.$locale)}`;this.saveError='';}}).catch(e=>{if(version===this.saveVersion){this.saveStatus='Cambios sin guardar';this.saveError=e.message||'Error de cuota o almacenamiento.';}});},
    act(fn){this.error='';try{fn();}catch(e){this.error=e.message;}},
    pending(){return !!this.$refs.formationEditor?.dirty||!!this.$refs.stadiumsEditor?.dirty||!!this.$refs.scenariosEditor?.dirty||!!this.$refs.mainMenu?.dirty||!!this.$refs.pixel?.dirty||!!this.$refs.pixel?.importImage||!!this.audioReplacement||!!this.audioSource||this.audioBusy||!!this.namePreview||!!this.groupPreview||!!this.groupTextError||!!this.titleTextPreview||!!this.titleTextError;},allowNavigate(){return !this.pending()||confirm(this.$t('Hay una previsualización que todavía no se aplicó a la ROM. ¿Descartar esa previsualización?'));},
    navigate(section){if(this.section===section)return;if(!this.allowNavigate())return;this.clearAudio();this.discardTeamName();this.discardGroupText();this.discardTitleText();this.section=section;if(section==='players')this.refresh();},changeTeam(event){if(!this.allowNavigate()){event.target.value=this.teamIndex;return;}this.teamIndex=Number(event.target.value);this.graphicId='';this.namePreview=null;this.selectedPlayers=[];this.hairPlayer=null;this.refresh();},
    changeGraphic(event){if(!this.allowNavigate()){event.target.value=this.graphic.id;return;}this.discardTeamName();this.graphicId=event.target.value;this.discardGroupText();this.discardTitleText();},
    discardTitleText(){this.titleTextPreview=null;this.titleTextError='';if(this.graphic.kind==='title-legal')this.titleLegalText=this.graphic.text;},
    previewTitleText(){this.titleTextPreview=null;this.titleTextError='';if(this.titleLegalText===this.graphic.text)return;try{if(this.$refs.pixel?.dirty||this.$refs.pixel?.importImage)throw new Error('Aplica o descarta el dibujo pendiente antes de generar textos.');this.titleTextPreview=previewTitleLegalText(this.project.original,this.graphic.id,this.titleLegalText);}catch(e){this.titleTextError=e.message;}},
    applyTitleText(){this.act(()=>{if(this.$refs.pixel?.dirty||this.$refs.pixel?.importImage)throw new Error('Aplica o descarta el dibujo pendiente antes de generar textos.');if(!this.titleTextPreview||this.titleTextError)return;this.project.transaction(titleLegalTextPatches(this.project.original,this.rom,this.graphic.id,this.titleLegalText));this.changed();});},
    discardGroupText(){this.groupPreview=null;this.groupTextError='';if(this.graphic.kind==='group-label')this.groupNameText=groupTexts(this.rom)[Number(this.graphic.id.split(':')[1])];},
    previewGroupName(){this.groupTextError='';this.groupPreview=null;try{if(this.$refs.pixel?.dirty)throw new Error('Aplica o descarta el dibujo pendiente antes de generar textos.');this.groupPreview=previewGroupText(this.project.original,this.graphic,this.groupNameText);}catch(e){this.groupTextError=e.message;}},
    applyGroupName(){this.act(()=>{if(!this.groupPreview||this.groupTextError)return;this.project.transaction(groupTextPatches(this.project.original,this.rom,this.graphic,this.groupNameText));this.groupPreview=null;this.changed();this.discardGroupText();this.discardTitleText();});},

    editTeamLabel(){this.graphicId=this.resources.find(r=>r.label==='Rótulo del equipo').id;this.navigate('graphics');},
    discardTeamName(){this.namePreview=null;if(!this.activeTeams.length){this.committedNames={small:'',large:''};this.smallNameText='';this.bigNameText='';return;}this.committedNames=teamNameTexts(this.project.original,this.rom,this.teamIndex);this.smallNameText=this.committedNames.small;this.bigNameText=this.committedNames.large;},
    previewTeamName(){
      const small=this.smallNameText.trim().toUpperCase(),large=this.bigNameText.trim().toUpperCase();
      if(small===this.committedNames.small&&large===this.committedNames.large){this.namePreview=null;return;}
      const result={patches:[],small:this.graphic,large:this.largeLabel,errors:{small:'',large:''}};
      if(this.$refs.pixel?.dirty){result.errors.small='Aplica o descarta el dibujo pendiente antes de generar textos.';this.namePreview=markRaw(result);return;}
      for(const [kind,text,build] of [['small',small,smallTeamNamePatches],['large',large,bigTeamNamePatches]]){
        if(text===this.committedNames[kind])continue;
        try{const patches=build(this.project.original,this.rom,this.teamIndex,text),preview=this.rom.slice();patches.forEach(p=>preview.set(p.bytes,p.offset));result.patches.push(...patches);result[kind]=kind==='large'?bigLabel(preview,this.teamIndex):graphicResources(preview,this.teamIndex).find(r=>r.kind==='label');}
        catch(e){result.errors[kind]=e.message;if(kind==='large')result.large=previewBigTeamText(this.rom,text);else {try{result.small={...this.graphic,matrix:compactTeamName(this.project.original,text)};}catch{result.small={...this.graphic,matrix:Array.from({length:8},()=>Array(32).fill(0))};}}}
      }
      this.namePreview=markRaw(result);
    },
    applyTeamName(){this.act(()=>{if(this.$refs.pixel?.dirty)throw new Error('Descarta el dibujo pendiente antes de aplicar los nombres.');if(!this.namePreview||Object.values(this.namePreview.errors).some(Boolean))throw new Error('Corrige los textos antes de aplicarlos.');this.project.transaction(this.namePreview.patches);this.namePreview=null;this.changed();});},
    restoreTeamName(){if(!this.allowNavigate())return;this.act(()=>{if(this.project.createdTeamNames(this.teamIndex))this.project.restoreCreatedTeamNames(this.teamIndex);else this.project.transaction(restoreTeamLabelPatches(this.project.original,this.rom,this.teamIndex));this.namePreview=null;this.changed();});},
    updateMainMenu(patches){this.act(()=>{this.project.transaction(patches);this.changed();});},
    updateStadium(patches){this.act(()=>{this.project.transaction(patches);this.changed();});},
    restoreStadium(index){this.act(()=>{this.project.transaction(restoreStadiumPatches(this.project.original,this.rom,index));this.changed();});},
    restoreStadiums(){this.act(()=>{const original=this.project.original;this.project.transaction([...STADIUM_RULES.map(([id,offset,size])=>({id,offset,bytes:original.slice(offset,offset+size)})),...stadiumGraphicRules(original).map(r=>({id:r.id,offset:r.offset,bytes:original.slice(r.offset,r.offset+r.size)}))]);this.changed();});},
    updateScenario(index,changes){this.act(()=>{this.project.transaction([scenarioPatch(this.rom,index,scenarioStartChanges(readScenarios(this.rom)[index],changes,this.rom))]);this.changed();});},
    updateScenarioDifficulty(index,value){this.act(()=>{this.project.transaction([scenarioDifficultyPatch(index,value)]);this.changed();});},
    updateScenarioDescription(index,text){this.act(()=>{this.project.transaction([scenarioDescriptionPatch(this.rom,index,text)]);this.changed();});},
    restoreScenario(index){this.act(()=>{this.project.transaction([`scenario:${index}`,`scenario-text:${index}`,`scenario-difficulty:${index}`].flatMap(id=>this.project.restorePatches(id)));this.changed();});},
    restoreScenarios(){this.act(()=>{this.project.transaction([...SCENARIO_RULES,...SCENARIO_TEXT_RULES,...SCENARIO_DIFFICULTY_RULES].flatMap(([id])=>this.project.restorePatches(id)));this.changed();});},
    updateGroups(groups){this.act(()=>{this.project.transaction(editGroupsPatches(this.project.original,this.rom,groups));this.changed();});},
    restoreGroups(){this.act(()=>{this.project.restore('group-editor:data');this.changed();});},
    setFlagColumns(columns){this.act(()=>{this.project.transaction(editGroupsPatches(this.project.original,this.rom,this.groups,columns));this.changed();});},
    setAllStars(mode){this.act(()=>{this.project.transaction([allStarsPatch(this.project.original,mode)]);this.changed();});},
    applyFormationChanges(patch){this.act(()=>{this.project.transaction([patch]);this.changed();});},
    editPlayer(index,key,value,event){this.act(()=>{this.project.transaction(playerPatches(this.rom,this.teamIndex,index,{[key]:value}));this.changed();});if(this.error&&event)event.target.value=this.team.players[index][key];},
    selectAll(checked){this.selectedPlayers=checked?this.rows.map(r=>r.index):[];},batch(){this.act(()=>{this.project.transaction(this.selectedPlayers.flatMap(i=>playerPatches(this.rom,this.teamIndex,i,{[this.batchStat]:this.batchValue})));this.changed();});},
    copyRoster(){if(!confirm(this.$t(`¿Reemplazar los 20 jugadores de ${this.teams[this.teamIndex]} por la plantilla de ${this.teams[this.copySource]}? Los gráficos y el equipo no se duplican.`)))return;this.act(()=>{const source=readDeluxeTeam(this.rom,this.copySource);this.project.transaction(source.players.flatMap((p,i)=>playerPatches(this.rom,this.teamIndex,i,Object.fromEntries(['name','no','position','hair','skin',...this.stats].map(k=>[k,p[k]])),false)));this.changed();});},
    isModified(id){return this.patches.some(p=>p.id===id);},isPlayerModified(i){const p=playerOffsets(this.rom,this.teamIndex,i);return this.isModified(`name:${p.name}`)||this.isModified(`attributes:${p.attributes}`);},
    restorePlayer(i){this.act(()=>{const p=playerOffsets(this.rom,this.teamIndex,i);this.project.transaction([...this.project.restorePatches(`name:${p.name}`),...this.project.restorePatches(`attributes:${p.attributes}`)]);this.changed();});},
    paletteUsers(offset){const affected=[];for(let team=0;team<this.teams.length;team++)for(const table of [0x1027a,0x102d0,0x10326,0x1037c,0x103d2,0xe7d8]){const pointer=teamPointer(this.rom,table,team);if(!pointer)continue;const start=loRom(0x890000|pointer)+2,count=(word(this.rom,start-2)+1)/2;if(offset>=start&&offset<start+count*2&&!affected.includes(this.teams[team]))affected.push(this.teams[team]);}return affected;},
    editPalette(offset,color,event){const users=this.paletteUsers(offset);if(!confirm(this.$t(`Este color afecta a jugadores o recursos que usan esta paleta: ${users.map(name=>this.$t(name)).join(', ')}. ¿Aplicar color?`))){if(event)event.target.value=palette(this.rom,offset,1)[0];return;}this.act(()=>{this.project.transaction([{id:`palette:${offset}`,label:`Color de paleta · ${users.join(', ')}`,offset,bytes:rgb555(color)}]);this.changed();});if(this.error&&event)event.target.value=palette(this.rom,offset,1)[0];},
    skinColor(index,color,event){const p=this.team.players[index];let table=p.position===1?0x10326:0x1027a,indexInPalette=p.position===1?3:4;if(p.skin&&word(this.rom,0x1037c+this.teamIndex*2)){table=0x1037c;indexInPalette=2;}const offset=loRom(0x890000|word(this.rom,table+this.teamIndex*2))+2+indexInPalette*2;this.editPalette(offset,color,event);},
    uniformColors(modified){const rom=modified?this.rom:this.project.original,table=[0x1027a,0x102d0,0x10326].includes(this.paletteTable)?this.paletteTable:0x1027a,pointer=teamPointer(rom,table,this.teamIndex),count=table===0x10326?11:16,colors=palette(rom,loRom(0x890000|pointer)+2,count);if(table===0x10326)colors.unshift('transparent');while(colors.length<16)colors.push('transparent');colors[0]='transparent';return colors;},
    applyGraphic(matrix,colors){this.act(()=>{if(this.titleTextPreview||this.titleTextError)throw new Error('Aplica o descarta el texto de portada antes de guardar un dibujo.');if(this.groupPreview||this.groupTextError)throw new Error('Aplica o descarta el texto del grupo antes de guardar un dibujo.');if(this.namePreview)throw new Error('Aplica o descarta el nombre preparado antes de guardar un dibujo.');const resource=this.graphic,affected=['composite','portrait','group-label','title-legal','boot-screen','menu-layer','screen-text'].includes(resource.kind)?[]:this.teams.filter((_,i)=>graphicResources(this.project.original,i).some(r=>r.id===resource.id));if(affected.length>1&&!confirm(this.$t(`Este gráfico es compartido por ${affected.map(name=>this.$t(name)).join(', ')}. ¿Aplicar a todos sus usos?`)))return;this.project.transaction([...graphicPatches(this.project.original,this.rom,resource,matrix),...(resource.kind==='flag'&&colors?flagPalettePatches(this.rom,this.teamIndex,colors):[])]);this.changed();});},
    restoreGraphic(){if(!this.allowNavigate())return;this.act(()=>{const r=this.graphic;if(r.kind==='flag')this.project.transaction([...flagPatches(this.project.original,this.rom,this.teamIndex,this.originalGraphic.matrix),...flagPalettePatches(this.rom,this.teamIndex,this.originalGraphic.colors)]);else if(r.id==='main-menu:font')this.project.transaction(graphicPatches(this.project.original,this.rom,r,this.originalGraphic.matrix));else if(r.kind==='label')this.project.transaction(smallLabelPatches(this.project.original,this.rom,this.teamIndex,this.originalGraphic.matrix));else if(r.kind==='group-label')this.project.transaction(restoreGroupTextPatches(this.project.original,this.rom,r,this.originalGraphic.matrix));else if(['portrait','title-legal','boot-screen'].includes(r.kind))this.project.transaction(graphicPatches(this.project.original,this.rom,r,this.originalGraphic.matrix));else if(r.parts)this.project.transaction(r.parts.flatMap((p,i)=>r.editableParts&&!r.editableParts.includes(i)?[]:this.project.restorePatches(p.id)));else this.project.restore(r.id);this.changed();});},restoreResource(id){this.act(()=>{this.project.restore(id);this.changed();});},
    history(redo){if(!this.allowNavigate())return;this.clearAudio();this.namePreview=null;this.act(()=>{redo?this.project.redo():this.project.undo();this.changed();});},
    reset(){if(!confirm(this.$t('¿Restaurar todos los recursos de la ROM original? Puedes deshacer la operación.')))return;this.clearAudio();this.namePreview=null;this.act(()=>{this.project.reset();this.changed();});},
    exportRom(){if(this.pending()){this.error='Aplica o descarta la previsualización pendiente antes de exportar.';return;}this.act(()=>download(this.project.exportRom(),`ISSD-editado.${this.project.headerSize?'smc':'sfc'}`,'application/octet-stream'));},
    resetAllRom(){if(!confirm(this.$t('¿Resetear todo? Se eliminarán los datos guardados localmente y se recargará la página. Esta operación no se puede deshacer.')))return;window.indexedDB.databases().then((r) => {
    for (var i = 0; i < r.length; i++) window.indexedDB.deleteDatabase(r[i].name);
}).then(() => {
    window.location.reload();
});},
    exportProject(){if(this.pending()){this.error='Aplica o descarta la previsualización pendiente antes de descargar el proyecto.';return;}this.act(()=>download(JSON.stringify(this.project.record()),'ISSD-proyecto.json','application/json'));},
    async importProject(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(file.size>8000000){this.error='El proyecto supera el límite de 8 MB.';return;}try{const record=JSON.parse(await file.text()),project=await RomProject.import(record);if(!confirm(this.$t('¿Abrir el proyecto importado y reemplazar su guardado local?')))return;await storeProject(project.record());this.$emit('import-rom',new File([project.exportOriginal()],'ISSD-proyecto.sfc'));}catch(e){this.error=e.message;}},
    clearAudio(){this.audioNormalizeStatus='';this.audioDecodeVersion++;this.audioBusy=false;this.$refs.audio?.pause();if(this.audioUrl)URL.revokeObjectURL(this.audioUrl);this.audioUrl='';this.audioPreviewLabel='';this.audioReplacement=null;this.audioSource=null;this.audioRange=null;},
    discardAudioImport(){this.clearAudio();this.error='';},
    changeAudioPitch(){if(this.audioSource){this.audioReplacement=null;this.$refs.audio?.pause();}else this.clearAudio();},
    showAudio(samples,rate,autoplay=false,label='Recorte convertido para la ROM'){this.audioPreviewLabel=label;if(this.audioUrl)URL.revokeObjectURL(this.audioUrl);this.audioUrl=URL.createObjectURL(wavBlob(samples,Math.round(rate)));const url=this.audioUrl;this.$nextTick(()=>{if(this.audioUrl!==url)return;if(autoplay)this.$refs.audio?.play().catch(e=>{if(e.name!=='AbortError'&&this.audioUrl===url)this.error='No se pudo reproducir automáticamente. Usa los controles de audio para iniciar la reproducción.';});const canvas=this.$refs.waveform;if(!canvas)return;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#176be0';ctx.beginPath();for(let x=0;x<canvas.width;x++){const start=Math.floor(x*samples.length/canvas.width),end=Math.max(start+1,Math.floor((x+1)*samples.length/canvas.width));let min=0,max=0;for(let i=start;i<end;i++){min=Math.min(min,samples[i]||0);max=Math.max(max,samples[i]||0);}ctx.moveTo(x,50-min/32768*45);ctx.lineTo(x,50-max/32768*45);}ctx.stroke();});},
    changeAudioSample(){this.clearAudio();this.previewAudio();},
    previewAudio(){this.act(()=>{this.$refs.audio?.pause();this.showAudio(readAudioSample(this.rom,this.audioSamples[this.sampleIndex]),pitchRate(this.pitch),true,'Muestra actual de la ROM');});},
    async importAudioFile(file){
      if(this.audioInfo.reason){this.error=this.audioInfo.reason;return;}
      if(file.size>50000000){this.error='El audio supera el límite de 50 MB.';return;}
      this.clearAudio();this.error='';this.audioBusy=true;const version=this.audioDecodeVersion,sample=this.sampleIndex;
      try{const decoded=await decodeUploadedAudio(await file.arrayBuffer());if(version!==this.audioDecodeVersion||sample!==this.sampleIndex)return;if(!decoded.samples.length)throw new Error('El audio está vacío.');this.audioSource=markRaw({...decoded,name:file.name});}
      catch(e){if(version===this.audioDecodeVersion)this.error=e.message;}
      finally{if(version===this.audioDecodeVersion)this.audioBusy=false;}
    },
    prepareAudioTrim(range){if(!this.audioSource)return;this.act(()=>{this.audioRange=range;this.audioReplacement=null;const wav=trimAudio(this.audioSource,range.start,range.end),replacement=replacementAudio(this.rom,this.audioSamples[this.sampleIndex],wav,this.pitch);this.audioReplacement=markRaw(replacement);this.showAudio(replacement.samples,replacement.rate);});},
    playAudioTrim(){if(!this.audioReplacement)return;this.showAudio(this.audioReplacement.samples,this.audioReplacement.rate,true);},
    normalizeAppliedAudio(){this.act(()=>{const patches=normalizedAudioPatches(this.rom,this.project.patches);if(!patches.length)return;this.project.transaction(patches);this.changed();this.audioNormalizeStatus=`${patches.length} audios normalizados. Puedes deshacer este cambio.`;if(this.audioSource&&this.audioRange)this.prepareAudioTrim(this.audioRange);else this.previewAudio();});},
    applyAudio(){this.act(()=>{if(!this.audioReplacement)throw new Error('Prepara un recorte válido antes de aplicar.');this.project.transaction([this.audioReplacement.patch]);this.clearAudio();this.changed();});},restoreAudio(){this.clearAudio();this.restoreResource(`audio:${this.audioInfo.offset}`);},
    shortcuts(event){if(['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)||event.target.isContentEditable)return;if((event.ctrlKey||event.metaKey)&&['z','y'].includes(event.key.toLowerCase())){event.preventDefault();if(this.$refs.pixel){event.shiftKey||event.key==='y'?this.$refs.pixel.redo():this.$refs.pixel.undo();}else this.history(event.shiftKey||event.key==='y');}},
    beforeLeave(event){if(this.pending()||this.saveStatus==='Guardando…'||this.saveError){event.preventDefault();event.returnValue='';}},
  }
};
</script>
