gin:12px}@media(max-width:800px){.studio{grid-template-columns:1fr}.studio aside{position:static}.studio aside button{display:inline-block;width:auto}.workspace{padding:10px}}
.players-table{min-width:860px}.players-table td,.players-table th{vertical-align:middle}.players-table th{white-space:nowrap}.players-table input,.players-table select,.players-table button{margin:0;box-sizing:border-box}.players-table .number{width:60px}.players-table .name{width:112px}.players-table .hair-column{width:84px;min-width:84px;text-align:center}.players-table .hair{display:inline-flex;min-width:70px;justify-content:center;white-space:nowrap}.players-table .hair :deep(canvas){flex:none;max-width:none}.players-table .skin-column{min-width:152px}.players-table .skin-cell{flex-wrap:nowrap;gap:8px}.players-table .skin-cell select{min-width:112px}.players-table summary{white-space:nowrap}
